        dialog.set_detail("The folder is removed from the server. This cannot be undone.");
        dialog.set_buttons(&["Cancel", "Delete folder"]);
        dialog.set_cancel_button(0);
        dialog.set_default_button(0);
        let parent = self.parent_window();
