const PORTAL_BUS: &str = "org.freedesktop.portal.Desktop";
const PORTAL_PATH: &str = "/org/freedesktop/portal/desktop";
const PORTAL_SETTINGS: &str = "org.freedesktop.portal.Settings";
const PORTAL_APPEARANCE: &str = "org.freedesktop.appearance";
const PORTAL_COLOR_SCHEME: &str = "color-scheme";
const PORTAL_TIMEOUT_MS: i32 = 500;

/// The desktop's own colour-scheme preference, or `None` when nothing answers.
///
/// T-054: GTK 4.20 does not fold the desktop preference into
/// `gtk-application-prefer-dark-theme`. Measured on this session, the property
/// reads `false` while GNOME is set to `prefer-dark`, so resolving
/// `Theme::System` against it alone made the Settings choice "System" mean
/// "Light, always" no matter what the desktop was doing. The XDG settings
/// portal is the desktop-neutral answer, and it does track the session:
/// 1 is prefer-dark, 2 prefer-light, 0 no preference.
fn portal_prefers_dark() -> Option<bool> {
    let bus = gio::bus_get_sync(gio::BusType::Session, gio::Cancellable::NONE).ok()?;
    let args = (PORTAL_APPEARANCE, PORTAL_COLOR_SCHEME).to_variant();
    // `ReadOne` is the current call; `Read` is what older portals answer to.
    let scheme = ["ReadOne", "Read"].into_iter().find_map(|method| {
        let reply = bus
            .call_sync(
                Some(PORTAL_BUS),
                PORTAL_PATH,
                PORTAL_SETTINGS,
                method,
                Some(&args),
                None,
                gio::DBusCallFlags::NONE,
                // A portal that never answers must not hold up the shell.
                PORTAL_TIMEOUT_MS,
                gio::Cancellable::NONE,
            )
            .ok()?;
        // `ReadOne` answers `(v)` and `Read` answers the same value boxed one
        // level deeper, so unwrap variants until a plain value is left.
        // The type is checked before unboxing: `as_variant` calls
        // `g_variant_get_variant` unguarded, so asking a `u32` for its inner
        // variant logs a GLib CRITICAL and returns nothing -- a portal read
        // that works but leaves an assertion failure in the journal.
        let mut value = reply.child_value(0);
        while value.is_type(glib::VariantTy::VARIANT) {
            let Some(inner) = value.as_variant() else {
                break;
            };
            value = inner;
        }
        value.get::<u32>()
    })?;
    Some(scheme == 1)
}

/// The desktop's own `gtk-application-prefer-dark-theme`, read once and kept.
///
/// T-137: this property is both the portal's stand-in when no portal answers
/// (`refresh_desktop_dark`) and the switch the shell now throws to make GTK
/// draw its titlebar dark (`apply_gtk_color_scheme`). Reading it live after
/// the shell has written it would mean asking the desktop a question and
/// hearing our own answer: pick Dark once and "System" would stay dark for
/// the rest of the session even on a light desktop. So the desktop's value is
/// latched before the first write and that latch is what the fallback reads.
static DESKTOP_GTK_DARK: OnceLock<bool> = OnceLock::new();

fn desktop_gtk_dark() -> bool {
    *DESKTOP_GTK_DARK.get_or_init(|| {
        gtk::Settings::default()
            .map(|s| s.is_gtk_application_prefer_dark_theme())
            .unwrap_or(false)
    })
}

/// T-137: draw GTK's own chrome in the shell's colour scheme.
///
/// Everything the stylesheet does not reach -- the CSD titlebar and its
/// window buttons, scrollbars, tooltips, the portal's own dialogs -- comes
/// from the desktop theme, and the theme picks its light or dark variant off
/// this one property. Set it and the top of the window follows the app.
fn apply_gtk_color_scheme(dark: bool) {
    // Latch the desktop's answer before overwriting it; see DESKTOP_GTK_DARK.
    let _ = desktop_gtk_dark();
    let Some(settings) = gtk::Settings::default() else {
        return;
    };
    if settings.is_gtk_application_prefer_dark_theme() != dark {
        settings.set_gtk_application_prefer_dark_theme(dark);
    }
}

/// Cached because this is read on every CSS load and on every watch pass that
/// paints the theme toggle; a synchronous D-Bus round trip per frame would eat
/// the 16 ms budget on its own. `Msg::DesktopColorSchemeChanged` refreshes it.
static DESKTOP_DARK: OnceLock<AtomicBool> = OnceLock::new();

fn refresh_desktop_dark() -> bool {
    let dark = portal_prefers_dark().unwrap_or_else(desktop_gtk_dark);
    DESKTOP_DARK
        .get_or_init(|| AtomicBool::new(dark))
        .store(dark, Ordering::Relaxed);
    dark
}

/// Follow the desktop's colour scheme for as long as the shell is open.
///
/// T-054: GTK reports nothing here, so the shell listens to the portal that
/// does. A "System" theme that only notices the desktop at startup is the
/// same defect as one that never notices it.
fn watch_desktop_color_scheme(sender: &ComponentSender<App>) {
    let Ok(bus) = gio::bus_get_sync(gio::BusType::Session, gio::Cancellable::NONE) else {
        return;
    };
    let tx = sender.input_sender().clone();
    let subscription = bus.subscribe_to_signal(
        Some(PORTAL_BUS),
        Some(PORTAL_SETTINGS),
        Some("SettingChanged"),
        Some(PORTAL_PATH),
        None,
        gio::DBusSignalFlags::NONE,
        move |signal| {
            let namespace = signal
                .parameters
                .child_value(0)
                .get::<String>()
                .unwrap_or_default();
            let key = signal
                .parameters
                .child_value(1)
                .get::<String>()
                .unwrap_or_default();
            if namespace == PORTAL_APPEARANCE && key == PORTAL_COLOR_SCHEME {
                tx.emit(Msg::DesktopColorSchemeChanged);
            }
        },
    );
    // Dropping the handle unsubscribes, so it is parked for the life of the
    // process: a watch that ends the moment it is set up is not a watch.
    COLOR_SCHEME_WATCH.with(|slot| *slot.borrow_mut() = Some(subscription));
}

thread_local! {
    static COLOR_SCHEME_WATCH: RefCell<Option<gio::SignalSubscription>> =
        const { RefCell::new(None) };
}

fn prefer_dark() -> bool {
    match DESKTOP_DARK.get() {
        Some(cached) => cached.load(Ordering::Relaxed),
        None => refresh_desktop_dark(),
    }
}

/// Apply the screen state to the actual GTK page hosts immediately.
///
/// This is deliberately independent of Relm4's `#[watch]` scheduler.  The
/// model remains the source of truth, but navigation must not depend on when
/// the next watch pass happens to run: a stale allocation can leave a newly
/// selected page visually blank even though the window title and accessibility
/// tree already describe that page. The same rule applies to the Settings
/// overlay: without the immediate pass its card can keep a zero allocation
/// while the underlying Inbox remains visible. The walk is tiny and runs only
/// on navigation, not on every render.
fn sync_screen_visibility(window: &gtk::ApplicationWindow, screen: Screen) {
    let Some(root) = window.child() else {
        return;
    };

    let mut pending = vec![root];
    while let Some(widget) = pending.pop() {
        let visible = if widget
            .css_classes()
            .iter()
            .any(|class| class == "welcome-screen")
        {
            Some(screen == Screen::Welcome)
        } else if widget
            .css_classes()
            .iter()
            .any(|class| class == "add-account-screen")
        {
            Some(screen == Screen::AddAccount)
        } else if widget
            .css_classes()
            .iter()
            .any(|class| class == "inbox-screen")
        {
            Some(matches!(screen, Screen::Inbox | Screen::Settings))
        } else if widget
            .css_classes()
            .iter()
            .any(|class| class == "settings-overlay")
        {
            Some(screen == Screen::Settings)
        } else {
            None
        };
        if let Some(visible) = visible {
            widget.set_visible(visible);
            // GTK normally queues this through the property notification,
            // but the visibility is intentionally applied outside Relm4's
            // deferred watch pass. In XWayland a stale render node can
            // otherwise survive the model change even though accessibility
            // already exposes the new page.
            widget.queue_resize();
            widget.queue_allocate();
            widget.queue_draw();
        }

        let mut child = widget.first_child();
        while let Some(current) = child {
            child = current.next_sibling();
            pending.push(current);
        }
    }
}

/// Apply the Add-account wizard state to its child widgets immediately.
///
/// The top-level page fix above is not enough: the wizard changes several
/// sibling widgets (preset buttons, the IMAP form and
/// progress) while staying on the same `AddAccount` page.  Waiting for a
/// deferred Relm4 `#[watch]` pass can leave the newly-visible form with the
/// old sibling allocation, which presents a blank/frozen-looking card until
/// an unrelated expose event.  Stable CSS classes make this one small walk
/// the same canonical switch for every wizard state; the watches remain a
/// declarative mirror for later model changes.
/// T-165: the row of session accounts is part of the chooser, and it also
/// disappears entirely when the probe found nothing -- an empty row would
/// leave a hole above the presets. Pulled out of
/// [`sync_wizard_visibility`] so the rule can be asserted without a
/// window: both halves matter, and "always visible" or "visible on the
/// IMAP form too" are exactly the mistakes a widget test would not catch.
fn show_system_accounts(wizard: &Wizard, probing: bool, has_system_accounts: bool) -> bool {
    wizard.show_system() && !probing && has_system_accounts
}

/// The probe is a D-Bus round trip that can also go to the network, so
/// the Linux level can be on screen before the answer is. Saying so beats
/// both of the alternatives: a blank card (looks broken) and the "no
/// accounts here" instructions (a claim we cannot make yet, and which
/// would then be replaced by a list -- the screen contradicting itself).
fn show_system_probing(wizard: &Wizard, probing: bool) -> bool {
    wizard.show_system() && probing
}

/// The answer came back empty. This is the ordinary case on a session
/// with no account manager, so it is instructions, not an error: the
/// person has to go somewhere else (system settings) and come back.
fn show_system_empty(wizard: &Wizard, probing: bool, has_system_accounts: bool) -> bool {
    wizard.show_system() && !probing && !has_system_accounts
}

/// Level one. Two buttons, no list -- picking a branch is a separate
/// question from picking an account inside it.
fn show_source(wizard: &Wizard) -> bool {
    wizard.show_source()
}

/// The level's own lede, except where it would contradict what is under
/// it: "Accounts you are already signed into on this desktop" directly
/// above "No accounts here yet" is the screen arguing with itself. When
/// the instructions are showing they are the explanation.
fn show_lede(wizard: &Wizard, probing: bool, has_system_accounts: bool) -> bool {
    !wizard.step.lede().is_empty() && !show_system_empty(wizard, probing, has_system_accounts)
}

fn sync_wizard_visibility(
    window: &gtk::ApplicationWindow,
    wizard: &Wizard,
    probing: bool,
    has_system_accounts: bool,
) {
    let Some(root) = window.child() else {
        return;
    };
    let show_chooser = wizard.show_chooser();
    let show_source = show_source(wizard);
    let show_system_accounts = show_system_accounts(wizard, probing, has_system_accounts);
    let show_system_probing = show_system_probing(wizard, probing);
    let show_system_empty = show_system_empty(wizard, probing, has_system_accounts);
    let lede = wizard.step.lede();
    let show_lede = show_lede(wizard, probing, has_system_accounts);
    let show_form = wizard.show_form();
    let show_progress = wizard.show_progress();
    let show_spinner = wizard.step != WizardStep::Ready;
    let can_open_inbox = wizard.can_open_inbox();
    let show_error = wizard.error.is_some();
    let progress_label = wizard.step.label();
    let error_label = wizard.error.as_deref().unwrap_or("");

    let mut pending = vec![root];
    while let Some(widget) = pending.pop() {
        let classes = widget.css_classes();
        if classes.iter().any(|class| class == "wizard-chooser-lede") {
            widget.set_visible(show_lede);
            if let Some(label) = widget.downcast_ref::<gtk::Label>() {
                label.set_label(lede);
            }
        } else if classes.iter().any(|class| class == "wizard-provider") {
            widget.set_visible(show_chooser);
        } else if classes.iter().any(|class| class == "wizard-source") {
            widget.set_visible(show_source);
        } else if classes
            .iter()
            .any(|class| class == "wizard-system-accounts")
        {
            widget.set_visible(show_system_accounts);
        } else if classes.iter().any(|class| class == "wizard-system-probing") {
            widget.set_visible(show_system_probing);
        } else if classes.iter().any(|class| class == "wizard-system-empty") {
            widget.set_visible(show_system_empty);
        } else if classes.iter().any(|class| class == "wizard-imap-form") {
            widget.set_visible(show_form);
        } else if classes.iter().any(|class| class == "wizard-progress") {
            widget.set_visible(show_progress);
        } else if classes
            .iter()
            .any(|class| class == "wizard-progress-spinner")
        {
            widget.set_visible(show_spinner);
            if let Some(spinner) = widget.downcast_ref::<gtk::Spinner>() {
                spinner.set_spinning(show_spinner);
            }
        } else if classes.iter().any(|class| class == "wizard-progress-label") {
            if let Some(label) = widget.downcast_ref::<gtk::Label>() {
                label.set_label(progress_label);
            }
        } else if classes.iter().any(|class| class == "wizard-open-inbox") {
            widget.set_visible(can_open_inbox);
        } else if classes.iter().any(|class| class == "wizard-error-label") {
            widget.set_visible(show_error);
            if let Some(label) = widget.downcast_ref::<gtk::Label>() {
                label.set_label(error_label);
            }
        }

        if classes.iter().any(|class| {
            matches!(
                class.as_str(),
                "wizard-chooser-lede"
                    | "wizard-provider"
                    | "wizard-source"
                    | "wizard-system-accounts"
                    | "wizard-system-probing"
                    | "wizard-system-empty"
                    | "wizard-imap-form"
                    | "wizard-progress"
                    | "wizard-progress-spinner"
                    | "wizard-progress-label"
                    | "wizard-open-inbox"
                    | "wizard-error-label"
            )
        }) {
            widget.queue_resize();
            widget.queue_allocate();
            widget.queue_draw();
        }

        let mut child = widget.first_child();
        while let Some(current) = child {
            child = current.next_sibling();
            pending.push(current);
        }
    }
}

fn app_mark() -> gtk::gdk::Texture {
    static MARK: OnceLock<gtk::gdk::Texture> = OnceLock::new();
    MARK.get_or_init(|| {
        let bytes = glib::Bytes::from_static(include_bytes!("../../../icon.png"));
        gtk::gdk::Texture::from_bytes(&bytes).expect("icon.png")
    })
    .clone()
}

