fn focused_is_editable(host: &impl IsA<gtk::Widget>) -> bool {
    let Some(root) = host.root() else {
        return false;
    };
    let Some(focus) = root.focus() else {
        return false;
    };
    focus.is::<gtk::Entry>()
        || focus.is::<gtk::TextView>()
        || focus.is::<gtk::Text>()
        || focus.is::<gtk::PasswordEntry>()
}

