    /// Mutation: `queue_mark_read_selected` in the Skip or ArmDelay arm
    /// of the adapter marks in Manual while the pure effect tests stay
    /// green. The name may appear exactly once, on the Dispatch arm.
    #[test]
    fn apply_mark_read_on_select_queues_only_on_dispatch() {
        let src = include_str!("shell.rs");
        let body = extract_brace_body(
            src,
            "fn apply_mark_read_on_select(&mut self, sender: &ComponentSender<Self>) {",
        );
        let dispatch = body
            .find("MarkReadOnSelect::Dispatch")
            .expect("Dispatch arm");
        let delay = body
            .find("MarkReadOnSelect::ArmDelay")
            .expect("ArmDelay arm");
        let skip = body.find("MarkReadOnSelect::Skip").expect("Skip arm");
        assert!(
            body[dispatch..delay].contains("queue_mark_read_selected"),
            "Immediate/Dispatch must still queue MarkRead"
        );
        assert!(
            !body[delay..skip].contains("queue_mark_read_selected"),
            "ArmDelay must only arm the timer, not queue"
        );
        assert!(
            !body[skip..].contains("queue_mark_read_selected"),
            "Skip/Manual must not queue"
        );
    }

    /// Leaving the thread by folder/account/filter keeps `selected` and
