    /// be the bump (OpenSearchHit calls it after arming Delay).
    #[test]
    fn leaving_via_folder_account_or_filter_cancels_mark_read_delay() {
        let src = include_str!("shell.rs");
        for (marker, label) in [
            ("Msg::SelectFolder(id) if inbox => {", "SelectFolder"),
            ("Msg::SetFilter(filter) if inbox => {", "SetFilter"),
            ("Msg::SwitchAccount(id) => {", "SwitchAccount"),
        ] {
            let body = extract_brace_body(src, marker);
            assert!(
                body.contains("cancel_pending_mark_read_delay"),
                "{label} must bump mark_read_gen so a Delay armed on the \
                 previous row does not fire after the user has left"
            );
        }
        let reload = extract_brace_body(
            src,
            "fn reload_list(&mut self, sender: &ComponentSender<Self>) {",
        );
        assert!(
            !reload.contains("cancel_pending_mark_read_delay") && !reload.contains("mark_read_gen"),
            "reload_list must not cancel Delay — OpenSearchHit reloads \
             after arming the timer"
        );
    }

