    /// T-054: a standing action in Settings -- one the page offers whether
    /// or not anything is wrong -- is a bordered pill in the approved
    /// design, not the quiet borderless `.ghost` that the second half of a
    /// pair wears.
    #[test]
    fn the_standing_settings_actions_are_bordered_pills() {
        let css = include_str!("style.css");
        let start = css
            .find(&joined(&["button.ghost.", "pill {"]))
            .expect("the pill form of a ghost button must be styled");
        let rule = &css[start..start + css[start..].find('}').expect("the rule closes")];
        for declaration in [
            "border: 1px solid @stroke_soft;",
            "border-radius: 999px;",
            "padding: 0 12px;",
        ] {
            assert!(
                rule.contains(declaration),
                "a standing action drawn as bare grey text does not read as \
                 something to press; `{declaration}` is missing"
            );
        }

        let src = include_str!("shell.rs");
        let ghost = joined(&["add_css_class(\"gho", "st\");"]);
        let pill = joined(&["add_css_class(\"pi", "ll\");"]);

        // Every ghost on a Settings page wears the pill. `ui-preview` spells
        // the exception out with `border: 0`, and on these pages it has
        // exactly one: `Remove`, the destructive half of the account row.
        let refill = extract_brace_body(
            src,
            "fn refill_settings(&self, sender: &ComponentSender<Self>) {",
        );
        let quiet: Vec<&str> = refill
            .match_indices(&ghost)
            .filter(|(at, _)| !refill[*at..refill.len().min(at + 120)].contains(&pill))
            .map(|(at, _)| &refill[at.saturating_sub(220)..at])
            .collect();
        assert_eq!(
            quiet.len(),
            1,
            "a Settings action without the pill renders as bare grey text; \
             only the destructive half of a pair is allowed to be quiet"
        );
        assert!(
            quiet[0].contains(&joined(&["with_label(\"Rem", "ove\")"])),
            "the one quiet ghost on a Settings page is `Remove`"
        );

        // The same shape away from the Settings pages.
        let custom = joined(&["\"Set custom ", "time\")"]);
        let at = src
            .find(&custom)
            .expect("the snooze popover must still offer a custom time");
        assert!(
            src[at..src.len().min(at + 300)].contains(&pill),
            "`{custom}` stands alone in its row, so it wears the pill"
        );
        let back = src
            .find(&joined(&["set_label: \"Ba", "ck\","]))
            .expect("the Add-account wizard must still offer Back");
        assert!(
            src[back.saturating_sub(320)..back]
                .contains(&joined(&["add_css_class: \"provider-", "btn\","])),
            "Back is the only action of its screen, and `ui-preview` draws it \
             with the same border and height as the presets above it"
        );

        // And the quiet form, which is just as deliberate: the second half of
        // a pair, and a row of a menu.
        for (anchor, why) in [
            (
                joined(&["with_label(\"Save dr", "aft\")"]),
                "the compose footer",
            ),
            (
                joined(&["with_label(\"Disc", "ard\")"]),
                "the compose footer",
            ),
            (
                joined(&["with_label(\"Add acc", "ount\")"]),
                "the account menu",
            ),
        ] {
            let at = src
                .find(&anchor)
                .unwrap_or_else(|| panic!("the shell must still offer `{anchor}`"));
            assert!(
                !src[at..src.len().min(at + 200)].contains(&pill),
                "`{anchor}` in {why} is quiet by design; a border there makes \
                 two competing buttons out of an action and its afterthought"
            );
        }
    }

