    /// T-125, D4: the section cache answers a repeat visit and never grows
    /// past its ceiling. The owner's words: "if it was loaded recently, do
    /// not load it for an eternity again -- show it at once, cache it
    /// properly". Properly is the second half: a mailbox-sized cache would
    /// trade the wait for memory the app is not allowed to take (D4).
    #[test]
    fn a_revisited_section_comes_back_from_a_bounded_cache() {
        fn page(total: usize) -> ThreadPage {
            ThreadPage {
                threads: Vec::new(),
                next: None,
                prev: None,
                total,
            }
        }

        let mut cache = SectionCache::default();
        cache.store("a|inbox|all".into(), &page(1));
        assert_eq!(
            cache.take_fresh("a|inbox|all").map(|p| p.total),
            Some(1),
            "the section just visited must come back without a query"
        );
        assert!(
            cache.take_fresh("a|archive|all").is_none(),
            "a section never visited has nothing honest to show"
        );

        // Re-storing a section is a visit, not a second entry.
        cache.store("a|inbox|all".into(), &page(2));
        assert_eq!(cache.holds().len(), 1);
        assert_eq!(cache.take_fresh("a|inbox|all").map(|p| p.total), Some(2));

        for i in 0..LIST_CACHE_SECTIONS {
            cache.store(format!("a|folder-{i}|all"), &page(i));
        }
        assert_eq!(
            cache.holds().len(),
            LIST_CACHE_SECTIONS,
            "the ceiling is a ceiling"
        );
        assert!(
            cache.take_fresh("a|inbox|all").is_none(),
            "and the section evicted is the one shown longest ago"
        );

        cache.clear();
        assert!(cache.holds().is_empty());
    }

    /// T-125: the owner opened a section they had just been in and waited
    /// through the same load again. A section already fetched this session
    /// is painted on the click; the query still runs behind it, and an
    /// answer equal to what is on screen changes nothing -- no clear, no
    /// rebuild, no scroll jump.
    #[test]
    fn a_recently_loaded_section_is_shown_before_it_is_fetched() {
        let src = include_str!("shell.rs");
        let reload = extract_brace_body(
            src,
            "fn reload_messages(&mut self, sender: &ComponentSender<Self>) {",
        );
        let cached = reload
            .find("show_cached_section")
            .expect("a repeat visit must not sit behind the skeleton");
        let fetch = reload.find("fetch_page").expect("and must still refetch");
        assert!(
            cached < fetch,
            "the cached page goes up on the click, not after the query"
        );

        let show = extract_brace_body(
            src,
            "fn show_cached_section(&mut self, sender: &ComponentSender<Self>) {",
        );
        assert!(
            show.contains("self.list_ready = true") && show.contains("self.render_page(page,"),
            "showing a cached section means real rows and no skeleton"
        );
        assert!(
            show.contains("self.showing_cached = Some(page.clone())"),
            "and remembering what was shown, so the fetch can confirm it"
        );

        let loaded = extract_brace_body(src, "Msg::ThreadsLoaded { gen, first, page } => {");
        assert!(
            loaded.contains("self.list_cache.store(key, &page)"),
            "every first page is what the next visit to that section opens with"
        );
        assert!(
            loaded.contains("None if self.showing_cached.take().as_ref() == Some(&page) => {"),
            "a page equal to the one already on screen must not rebuild the list"
        );
        assert!(
            loaded.contains("None if !first => self.render_page(page, &sender)"),
            "and an older page scrolled into view must append, not replace --             the cached first page is on screen and reachable, so this race             is now a scroll away rather than impossible"
        );

        let failed = extract_brace_body(
            src,
            concat!(
                "Msg::ThreadsLoadFailed {\n                gen,\n",
                "                first,\n                message,\n            } => {"
            ),
        );
        assert!(
            failed.contains("let cached = self.showing_cached.take().is_some()")
                && failed.contains("if first && !cached"),
            "a failed refresh of cached rows, or a failed append, must not             blank the folder"
        );
    }

    /// T-125, D9: a cached page is Core's answer from a moment ago, and the
    /// moment it stops being true it goes. Hung on `wake_sync` because
    /// every local change already passes through there on its way to the
    /// server -- a mutation door added later cannot forget this one without
    /// also failing to reach IMAP.
    #[test]
    fn a_change_of_any_kind_drops_the_cached_sections() {
        let src = include_str!("shell.rs");
        let wake = extract_brace_body(src, "fn wake_sync(&mut self) {");
        assert!(
            wake.contains("self.invalidate_list_cache()"),
            "marks, stars, moves, archives, snoozes and undo all wake the             worker -- and all invalidate what the cache claims"
        );

        let invalidate = extract_brace_body(src, "fn invalidate_list_cache(&mut self) {");
        assert!(
            invalidate.contains("self.first_page_key = None"),
            "a page read before the change must not be stored as if it were             read after it"
        );

        let due = extract_brace_body(src, "Msg::SyncRefreshDue => {");
        let drop_at = due
            .find("self.invalidate_list_cache()")
            .expect("an inbound change invalidates too -- it wakes nothing here");
        let refresh = due
            .find("self.refresh_list_keeping_place(&sender)")
            .expect("T-105: and still refreshes in place");
        assert!(
            drop_at < refresh,
            "the stale pages go before the fresh one is asked for, or the             answer is filed under an invalidation that follows it"
        );
    }

    /// T-125: the second visit to a mailbox does not wait for
    /// `list_folders` to repeat which folder it opens on. The click sets
    /// that folder and starts the list; `Msg::AccountFocused` still lands,
    /// still rebuilds the sidebar, and simply has nothing left to change.
    #[test]
    fn a_second_visit_to_a_mailbox_starts_its_list_on_the_click() {
        let src = include_str!("shell.rs");
        let focus = extract_brace_body(
            src,
            "fn focus_account(&mut self, account_id: AccountId, sender: &ComponentSender<Self>) \
             -> bool {",
        );
        assert!(
            focus.contains("self.opening_folders.get(account_id.as_str())"),
            "the folder a mailbox opens on is learned once, not re-read per switch"
        );
        assert!(
            focus.contains("self.focus_opened = known"),
            "and whether the click got there first has to be knowable later"
        );

        let arm = extract_brace_body(src, "Msg::AccountFocused { gen, folders } => {");
        assert!(
            arm.contains("self.opening_folders")
                && arm.contains(".insert(account_id.as_str().to_string(), folder.clone())"),
            "this reply is where that folder is learned"
        );
        assert!(
            arm.contains("let already_open = self.focus_opened && self.folder == folder"),
            "a list the click already started must not be thrown away and             re-asked for -- and two folders reading `inbox` by fallback are             not evidence that it was started"
        );
        assert!(
            arm.contains("self.apply_nav(folders, chip_folders, &sender)"),
            "the sidebar still comes from this reply either way"
        );

        for marker in [
            "Msg::SwitchAccount(id) => {",
            concat!(
                "Msg::OpenNotification {\n                account_id,\n",
                "                thread_id,\n            } => {"
            ),
        ] {
            let door = extract_brace_body(src, marker);
            assert!(
                door.contains("let opened = self.focus_account(")
                    && door.contains(
                        "if opened {\n                        self.reload_messages(&sender);"
                    ),
                "{marker} must open a known mailbox on the click"
            );
            assert!(
                door.contains("} else {\n                        self.begin_list_switch(&sender);"),
                "{marker} must still put the skeleton up for a mailbox it has                  not seen before"
            );
        }
    }

    /// T-127: the owner closed the app on one mailbox and it opened on
    /// another every time. The window opens where they left it -- and
    /// falls back to the first mailbox when that place is gone, rather
    /// than to an empty pane or a toast about an account they removed
    /// themselves.
    #[test]
    fn the_window_opens_on_the_mailbox_it_was_closed_on() {
        let accounts = [
            fixture_account("work", "Work"),
            fixture_account("home", "Home"),
        ];
        assert_eq!(
            opening_mailbox(&accounts, Some(&AccountId("home".into()))),
            Some(AccountId("home".into())),
            "the mailbox the reader was in, not the first one"
        );
        assert_eq!(
            opening_mailbox(&accounts, None),
            Some(AccountId("work".into())),
            "a profile that never stored a place opens as it always did"
        );
        assert_eq!(
            opening_mailbox(&accounts, Some(&AccountId("removed".into()))),
            Some(AccountId("work".into())),
            "a mailbox removed since is simply not a place any more"
        );
        assert_eq!(opening_mailbox(&[], Some(&AccountId("work".into()))), None);

        let folders = [
            fixture_folder("work:inbox", FolderKind::Inbox, false),
            fixture_folder("work:sent", FolderKind::Sent, false),
        ];
        assert_eq!(opening_view_folder(false, 2, &folders), "work:inbox");
        assert_eq!(
            opening_view_folder(true, 2, &folders),
            format!("unified:{}", FolderKind::Inbox.as_str()),
            "the merged view is a place the reader can close the window on"
        );
        assert_eq!(
            opening_view_folder(true, 1, &folders),
            "work:inbox",
            "but not once there is only one mailbox left -- the menu stops             offering it, and it would be a view with no way back"
        );
        assert_eq!(opening_view_folder(false, 1, &[]), "inbox");

        // The write is debounced off the switch, and it is the switch --
        // not some settings screen -- that arms it.
        let src = include_str!("shell.rs");
        let focus = extract_brace_body(
            src,
            "fn focus_account(&mut self, account_id: AccountId, sender: &ComponentSender<Self>) \
             -> bool {",
        );
        assert!(
            focus.contains("self.remember_open_mailbox(false)"),
            "the one door onto an account is the one place that remembers it, \
             and an account is never the merged view"
        );
        let unified = extract_brace_body(src, "Msg::OpenUnified => {");
        assert!(
            unified.contains("self.remember_open_mailbox(true)"),
            "and the merged view is a place like any mailbox"
        );
        // T-135: the write is immediate and off-thread. Debouncing it by
        // 750 ms under the `core` mutex is what lost the merged view: the
        // GTK thread waited out SQLite's `busy_timeout` behind the
        // backfill, the flush failed, and the error was discarded.
        let persist = extract_brace_body(src, "fn remember_open_mailbox(&self, unified: bool) {");
        assert!(
            persist.contains("settings.last_account = account")
                && persist.contains("settings.last_unified = unified")
                && persist.contains("self.write_settings("),
            "both halves of the place are written, and written through the \
             settings writer thread"
        );
        assert!(
            !persist.contains("timeout_add_local_once") && !persist.contains("core.lock()"),
            "no debounce and no SQLite on the GTK thread: a switch made a \
             moment before quitting is a switch that happened"
        );
        assert!(
            !persist.contains("default_account"),
            "the preference is a different fact and this must not overwrite it"
        );
    }

    /// T-133. The owner: "все равно случается зависание интерфейса, его не
    /// должно быть вообще". The freeze they saw was one settings write on
    /// the GTK thread meeting SQLite's five-second `busy_timeout` behind
    /// the backfill worker. There is nothing to tune in that number -- the
    /// only fix is that this thread never writes settings at all, so the
    /// rule is checked here rather than left to the next edit's judgement.
    #[test]
    fn the_gtk_thread_never_writes_settings_itself() {
        let src = include_str!("shell.rs");
        let offenders: Vec<usize> = src
            .lines()
            .enumerate()
            .filter(|(_, line)| {
                let code = line.trim_start();
                if code.starts_with("//") {
                    return false;
                }
                // Split so this test's own source is not an offender.
                code.contains(concat!("patch_", "settings("))
                    || code.contains(concat!("flush_", "settings("))
            })
            .map(|(n, _)| n + 1)
            .collect();
        assert!(
            offenders.is_empty(),
            "settings must be written through App::write_settings (the writer \
             thread), not on the GTK thread -- lines {offenders:?}"
        );
        let door = extract_brace_body(
            src,
            "fn write_settings(&self, patch: impl FnOnce(&mut CoreSettings) + Send + 'static) {",
        );
        assert!(
            door.contains("self.settings_writer.write(patch)"),
            "and that door is the writer thread's channel, which never blocks"
        );
    }

    /// T-139/T-140/T-143. Same rule as settings, one table over: no mailbox
    /// write happens on the GTK thread.
    ///
    /// The owner reported both halves of what that costs -- "выбираю
    /// некоторые письма и они не маркируются прочитанными, а некоторые
    /// реально сразу" (a dispatch that lost the race, failed after five
    /// seconds, and had its error discarded) and "в all account нажал Mark
    /// all as read и все на долго зависло" (the same wait, in front of the
    /// reader). Both marks go through `mail_writer` now, and this is the
    /// guard that keeps them there.
    #[test]
    fn the_gtk_thread_never_marks_mail_read_itself() {
        let src = include_str!("shell.rs");
        for (marker, what) in [
            (
                "fn queue_mark_read_selected(&mut self, sender: &ComponentSender<Self>) {",
                "mark-read on select",
            ),
            (
                "fn mark_ids(&mut self, ids: Vec<String>, read: bool, sender: &ComponentSender<Self>) {",
                "the explicit mark",
            ),
            ("Msg::MarkFolderRead(id) if inbox => {", "mark a whole folder read"),
            (
                "fn archive_ids(&mut self, ids: Vec<String>, sender: &ComponentSender<Self>) {",
                "archive",
            ),
            (
                "fn snooze_ids_until(\n        &mut self,\n        ids: Vec<String>,\n        until: i64,\n        label: &'static str,\n        sender: &ComponentSender<Self>,\n    ) {",
                "snooze",
            ),
            // The doors T-143 had named as out of scope, closed since.
            (ACT_ON_IDS_SIGNATURE, "trash"),
            (
                concat!(
                    "fn act_on_ids_irreversible(\n        &mut self,\n        ids: Vec<String>,\n",
                    "        sender: &ComponentSender<Self>,\n        label: &'static str,\n",
                    "        build: impl Fn(AccountId, Vec<ThreadId>) -> Command + Send + 'static,\n    ) {",
                ),
                "permanent delete",
            ),
            (
                "fn unsnooze_ids(&mut self, ids: Vec<String>, sender: &ComponentSender<Self>) {",
                "unsnooze",
            ),
            ("Msg::Undo => {", "undo"),
            ("Msg::DiscardDraft => {", "discard a draft"),
            ("Msg::RemoveAttachment(id) => {", "remove an attachment"),
            // T-163: folder CRUD, the two account doors and Move -- the
            // last writes this file did on the GTK thread.
            ("fn move_ids(&mut self, ids: Vec<String>, folder_id: String, sender: &ComponentSender<Self>) {", "move"),
            ("Msg::CreateFolder if inbox => {", "create a folder"),
            ("Msg::RenameFolder if inbox => {", "rename a folder"),
            ("Msg::DeleteFolderConfirmed(folder_id) => {", "delete a folder"),
            ("Msg::SaveAccountName { id, name } => {", "rename an account"),
            ("Msg::RemoveAccountConfirm(id) => {", "remove an account"),
        ] {
            let body = extract_brace_body(src, marker);
            assert!(
                !body.contains("self.core.lock()"),
                "{what} must not take the profile's write lock on this thread"
            );
        }
        let grouped = extract_brace_body(src, GROUPED_ASYNC_SIGNATURE);
        assert!(
            grouped.contains("self.group_ids_by_account(ids)")
                && grouped.contains("self.mail_writer.run("),
            "the grouping is cheap and stays here; the dispatch is what leaves"
        );
        assert!(
            grouped.contains("with_retries(core, |core| {"),
            "a write that only lost the race must be tried again -- that is \
             the difference between a letter that gets marked and one that \
             quietly does not"
        );
    }

    /// T-139: a mark the database refused is said out loud, and the row
    /// goes back to what the database actually holds.
    ///
    /// This is the defect itself: the old path was `let _ = ...dispatch(..)`
    /// on the GTK thread, so a failed mark left a letter looking read for
    /// one repaint and unread ever after, with nothing anywhere saying why.
    #[test]
    fn a_mark_the_database_refused_is_not_lost_in_silence() {
        let src = include_str!("shell.rs");
        let landed = extract_brace_body(
            src,
            concat!(
                "Msg::MarkWritten {\n                ids,\n                read,\n",
                "                announce,\n                tickets,\n",
                "                error,\n            } => {"
            ),
        );
        assert!(
            landed.contains("Some(message) => self.show_toast(&message, &sender)"),
            "the reader has to be told, not left with a bold letter"
        );
        assert!(
            landed
                .contains("for id in &ids {\n                    self.rebind_thread(id, &sender);"),
            "and the rows are re-read from Core either way, so the optimistic \
             paint cannot outlive a write that failed"
        );
        let select = extract_brace_body(
            src,
            "fn queue_mark_read_selected(&mut self, sender: &ComponentSender<Self>) {",
        );
        let paint = select
            .find("self.paint_rows_read(")
            .expect("the row is painted");
        let write = select
            .find("self.mail_writer.run(")
            .expect("the write is queued");
        assert!(
            paint < write,
            "the dot goes on the click, not when SQLite gets round to it"
        );
    }

    /// T-133: a label is a variant name, never a payload. If `msg_label`
    /// ever started printing fields, a `Msg::BodyPrepared` on a real
    /// mailbox would put message text on stderr (D14).
    #[test]
    fn a_dispatch_label_names_the_message_and_carries_no_content() {
        assert_eq!(msg_label(&Msg::PollSyncProgress), "PollSyncProgress");
        assert_eq!(
            msg_label(&Msg::SelectFolder("work:secret-folder".into())),
            "SelectFolder",
            "a tuple variant stops at the payload"
        );
        assert_eq!(
            msg_label(&Msg::PersistSidebarWidth { gen: 7 }),
            "PersistSidebarWidth",
            "and a struct variant stops at the brace"
        );
        assert!(
            !msg_label(&Msg::HtmlLinkActivated("https://tracker.example/x".into()))
                .contains("tracker"),
            "no payload may reach stderr"
        );
    }

    /// T-136. The owner: "смотрю письма которые загружал ранее, в карточке
    /// у них всё заполнено, но когда открываю письмо оно начинает
    /// грузиться и делает это крайне медленно". The body was on disk the
    /// whole time -- the lookup was queued behind the sidebar recount and
    /// the warm-up scan on the one `reader` mutex. A click on a letter
    /// gets a handle nothing else uses.
    #[test]
    fn opening_a_letter_never_queues_behind_the_list_and_the_sidebar() {
        let src = include_str!("shell.rs");
        let lookup = extract_brace_body(
            src,
            "fn lookup_body_async(&mut self, id: MessageId, sender: &ComponentSender<Self>) {",
        );
        assert!(
            lookup.contains(concat!("Arc::clone(&self.", "letter)")),
            "the letter path must use its own Core handle"
        );
        assert!(
            !lookup.contains("Arc::clone(&self.reader)"),
            "and never the handle the list, the sidebar, search and the \
             warm-up scan all share"
        );
        // The other way round is just as important: `letter` is for this
        // one caller, so a long scan can never be started on it.
        let uses: Vec<&str> = src
            .lines()
            .filter(|line| {
                let code = line.trim_start();
                // Split so this test's own source is not a caller, and
                // anchored on the clone so `letter_body`/`letter_pane`
                // (widgets, not handles) are not swept up.
                !code.starts_with("//") && code.contains(concat!("Arc::clone(&self.", "letter)"))
            })
            .collect();
        assert_eq!(
            uses.len(),
            1,
            "exactly one caller may hold the reading pane's handle, found: {uses:?}"
        );
    }

    /// T-128: the fetching strip must not blink out between two passes of
    /// the same sync. The owner, on startup: "the fetch counter appears,
    /// then disappears, then appears again". Mutation: settle regardless
    /// of the generation, and a folder that started again goes dark.
    #[test]
    fn the_fetching_strip_is_held_across_the_gap_between_passes() {
        let inbox = (AccountId("work".into()), "work:inbox".to_string());
        let sent = (AccountId("work".into()), "work:sent".to_string());
        let mut strip = FetchingStrip::default();

        assert_eq!(
            strip.ending(&inbox),
            None,
            "nothing to hold for a folder that was not running"
        );

        strip.started(inbox.clone());
        assert!(strip.running.contains(&inbox));
        let first = strip.ending(&inbox).expect("a running pass can end");
        assert!(
            strip.running.contains(&inbox),
            "the strip stays up while the hold runs -- that is the whole point"
        );

        // The next folder of the same sync starts before the hold expires.
        strip.started(inbox.clone());
        assert!(
            !strip.settled(&inbox, first),
            "the pending removal is for a pass that has been superseded"
        );
        assert!(
            strip.running.contains(&inbox),
            "and it must not take down a strip that is true again"
        );

        let second = strip.ending(&inbox).expect("the new pass ends too");
        assert_ne!(first, second, "each hold is its own generation");
        assert!(strip.settled(&inbox, second));
        assert!(
            !strip.running.contains(&inbox),
            "a sync that really is over leaves the strip down -- a hold that             never expires would be a spinner for the rest of the session"
        );
        assert!(
            strip.settling.is_empty(),
            "and nothing is left waiting on a timer that already fired"
        );

        // Holds are per folder: one settling must not clear another.
        strip.started(inbox.clone());
        strip.started(sent.clone());
        let held = strip.ending(&sent).expect("sent ends first");
        assert!(strip.settled(&sent, held));
        assert!(
            strip.running.contains(&inbox),
            "the folder still fetching keeps the strip up on its own"
        );
    }

    /// T-097(11): the New-folder popover offers a colour, and the colours it
    /// offers are Core's. A sixth swatch here would be a colour
    /// `create_folder_with_color` silently drops, which is a picker that
    /// lies.
    #[test]
    fn the_new_folder_colour_picker_offers_exactly_cores_palette() {
        for hex in FOLDER_PALETTE {
            assert_ne!(
                folder_color_name(hex),
                "Folder colour",
                "{hex} has no name, so its swatch has no accessible label"
            );
        }
        let classes: HashSet<String> = FOLDER_PALETTE
            .iter()
            .map(|hex| dot_class_from_hex(Some(hex)))
            .collect();
        assert_eq!(
            classes.len(),
            FOLDER_PALETTE.len(),
            "two swatches would be drawn in the same colour"
        );

        let src = include_str!("shell.rs");
        let swatches = extract_brace_body(
            src,
            "fn folder_color_swatches() -> (gtk::Box, Vec<gtk::ToggleButton>) {",
        );
        assert!(
            swatches.contains("for hex in FOLDER_PALETTE.iter().copied()"),
            "the swatches must be built from the palette, not from a second              list of hexes that can drift from it"
        );
        assert!(
            swatches.contains("swatch.set_group(Some(first))"),
            "the toggles must be one group -- the active one is the answer,              and two active swatches would have no answer"
        );

        let arm = extract_brace_body(src, "Msg::CreateFolder if inbox => {");
        assert!(
            arm.contains("create_folder_with_color(&account_id, &name, color)"),
            "the picked colour must reach Core"
        );
        let pick = extract_brace_body(
            src,
            "fn chosen_folder_color(&self) -> Option<&'static str> {",
        );
        assert!(
            pick.contains("FOLDER_PALETTE.get(index).copied()"),
            "the swatch index is the palette index -- the picker must not              carry its own copy of the hexes"
        );
    }

    /// T-061e: Unsnooze is the Snoozed list's own action, and it must stay
    /// distinct from Undo. Undo restores the pre-snooze state; this reuses
    /// the timer's transition through the single Core door.
    #[test]
    fn unsnooze_uses_the_core_door_and_is_not_undo() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::Unsnooze if inbox => {");
        assert!(
            arm.contains("self.unsnooze_ids(ids, &sender)"),
            "Msg::Unsnooze must go through the unsnooze_ids door"
        );
        let door = extract_brace_body(
            src,
            "fn unsnooze_ids(&mut self, ids: Vec<String>, sender: &ComponentSender<Self>) {",
        );
        assert!(
            door.contains("core.unsnooze_thread(&account_id, &thread_id)"),
            "unsnooze_ids must call the one Core transition"
        );
        for forbidden in [
            "consume_undo",
            "show_undo_toasts",
            "toast_tickets",
            "Command::",
            "self.store",
        ] {
            assert!(
                !door.contains(forbidden),
                "unsnooze_ids must not {forbidden} -- it is the timer's own \
                 transition run early, not an Undo and not a queued command"
            );
        }
        // The affordance only exists where it means something.
        let visible = extract_brace_body(src, "fn viewing_snoozed(&self) -> bool {");
        assert!(visible.contains("self.folder == \"snoozed\""));
        assert!(
            src.contains("set_visible: model.viewing_snoozed()"),
            "the Unsnooze button must be bound to the Snoozed view"
        );
    }

    /// T-032/T-033 fail-closed (mutation pin 3): hover Archive goes through
    /// the optimistic `archive_ids` Core door, while local Snooze goes
    /// through its explicit `snooze_ids_until` Core door.
    #[test]
    fn row_archive_and_snooze_dispatch_through_core_doors() {
        let src = include_str!("shell.rs");
        for (marker, cmd, door) in [
            (
                "Msg::RowArchive(id) if inbox => {",
                "Command::Archive",
                "archive_ids",
            ),
            (
                "Msg::RowSnooze(id) if inbox => {",
                "Command::Snooze",
                "snooze_ids_until",
            ),
        ] {
            let arm = extract_brace_body(src, marker);
            assert!(
                arm.contains(door),
                "{marker} must use its Core command door + {cmd}"
            );
            if marker.contains("Archive") {
                let archive = extract_brace_body(
                    src,
                    "fn archive_ids(&mut self, ids: Vec<String>, sender: &ComponentSender<Self>) {",
                );
                assert!(archive.contains(cmd));
                let hide = extract_brace_body(
                    src,
                    "fn hide_rows(&mut self, ids: &[String], sender: &ComponentSender<Self>) {",
                );
                assert!(
                    hide.contains("self.threads_gen += 1"),
                    "optimistic Archive must invalidate a pre-dispatch page fetch, or its stale reply can put the row back"
                );
            } else {
                let snooze = extract_brace_body(
                    src,
                    "fn snooze_ids_until(\n        &mut self,\n        ids: Vec<String>,\n        until: i64,\n        label: &'static str,\n        sender: &ComponentSender<Self>,\n    ) {",
                );
                assert!(snooze.contains(cmd));
            }
            for forbidden in [
                "self.store",
                "request_body",
                "spawn_prepare",
                "select_thread",
            ] {
                assert!(!arm.contains(forbidden), "{marker} must not {forbidden}");
            }
        }
    }

    /// T-143: Archive and Snooze are SQLite writes just like MarkRead. A
    /// hover click must only enqueue work on the GTK thread; otherwise a
    /// backfill transaction can turn Archive into an immediate error and
    /// make Snooze look like a no-op after waiting out `busy_timeout`.
    #[test]
    fn archive_and_snooze_leave_sqlite_to_the_mail_writer() {
        let src = include_str!("shell.rs");
        for marker in [
            "fn archive_ids(&mut self, ids: Vec<String>, sender: &ComponentSender<Self>) {",
            "fn snooze_ids_until(\n        &mut self,\n        ids: Vec<String>,\n        until: i64,\n        label: &'static str,\n        sender: &ComponentSender<Self>,\n    ) {",
        ] {
            let body = extract_brace_body(src, marker);
            assert!(
                body.contains("dispatch_grouped_async"),
                "{marker} must enqueue its Core dispatch on mail_writer"
            );
            assert!(
                !body.contains("dispatch_grouped(&"),
                "{marker} must not start a SQLite write on the GTK thread"
            );
        }
    }

    /// T-143: Immediate mark-read paints optimistically. No subsequent
