    /// T-036/T-060: one bulk Archive call may touch 1,000 ids, but it must
    /// still contain exactly one Core dispatch door. The loop which removes
    /// ids from the GTK-side selection is deliberately allowed; a second
    /// `dispatch`/`dispatch_with_receipt` inside that loop would make this
    /// test fail and reintroduce one transaction per row.
    #[test]
    fn bulk_archive_has_one_core_dispatch_door() {
        let src = include_str!("shell.rs");
        let body = extract_brace_body(
            src,
            "fn archive_ids(&mut self, ids: Vec<String>, sender: &ComponentSender<Self>) {",
        );
        assert_eq!(
            body.matches("dispatch_grouped").count(),
            1,
            "bulk Archive must dispatch one vector command, not one command per id"
        );
        assert!(
            !body.contains("dispatch_with_receipt"),
            "and it must not reach past dispatch_grouped to Core directly -- \
             that is the door that keeps a merged selection to one \
             transaction per mailbox"
        );
        assert!(body.contains("thread_ids"));
        assert!(body.contains("Command::Archive"));
        assert!(
            !body.contains("dispatch(Command::Archive"),
            "a per-row dispatch must not be added next to the batch receipt"
        );
    }

    /// T-032 fail-closed (mutation pin 6): the overflow list is the one
    /// source for both More buttons and holds only what the toolbar
    /// icons do not already show. Adding Archive/Delete/Snooze/Read here
    /// duplicates the toolbar and is red by name.
    #[test]
    fn overflow_items_has_no_toolbar_duplicates() {
        let src = include_str!("shell.rs");
        let body = extract_brace_body(src, "fn overflow_items() -> &'static [OverflowItem] {");
        for required in [
            "Msg::Reply)",
            "Msg::ReplyAll",
            "Msg::Forward",
            "Msg::StarSelected",
            "Msg::HideRemoteImages",
            "Msg::PermanentDelete",
        ] {
            assert!(
                body.contains(required),
                "overflow must offer {required} (not on the toolbar icons)"
            );
        }
        for forbidden in [
            "Msg::Archive",
            "Msg::Delete",
            "Msg::Snooze",
            "Msg::MarkRead",
            "Msg::MarkUnread",
        ] {
            assert!(
                !body.contains(forbidden),
                "overflow must not duplicate the toolbar's {forbidden}"
            );
        }
        let more = extract_brace_body(
            src,
            "fn more_button(tx: &relm4::Sender<Msg>) -> gtk::MenuButton {",
        );
        assert!(
            more.contains("overflow_items"),
            "both More buttons are built from overflow_items so they cannot drift"
        );
    }

    /// T-046 fail-closed: response action arms only hand off to the shared
    /// Core command helper; no local body fetch or direct draft mutation can
    /// creep back in next to a keyboard shortcut.
    #[test]
    fn response_arms_do_not_fetch_or_mutate_a_draft_inline() {
        let src = include_str!("shell.rs");
        for marker in [
            "Msg::Reply if inbox => {",
            "Msg::ReplyAll if inbox => {",
            "Msg::Forward if inbox => {",
        ] {
            let arm = extract_brace_body(src, marker);
            assert!(
                !arm.contains("request_body")
                    && !arm.contains("create_response_draft")
                    && !arm.contains("save_draft"),
                "{marker} must only delegate to begin_response_draft"
            );
        }
    }

    /// T-104: the warm-up has to survive the reader.
    ///
    /// Measured on the owner's mailbox: 18 of the newest 100 bodies cached,
    /// then flat for the rest of the session. `pump_prefetch` hands out
    /// nothing while the reading pane is waiting on a body of its own, and
    /// the only other caller was `on_body_ready` for the warm-up's own
    /// message -- so one click during a warm-up stopped it for good. Every
    /// exit from the reader's loading state now re-arms it.
    ///
    /// Mutation: drop the call from `apply_prepared_body` -> the warm-up
    /// stops at the first opened message again.
    #[test]
    fn the_warm_up_restarts_when_the_reader_stops_waiting() {
        let src = include_str!("shell.rs");
        let prepared = extract_brace_body(
            src,
            "fn apply_prepared_body(&mut self, prepared: PreparedBody, sender: &ComponentSender<Self>) {",
        );
        assert!(
            prepared.contains("self.pump_prefetch(sender);"),
            "a body that finished preparing is the reader no longer waiting"
        );
        let pump = extract_brace_body(
            src,
            "fn pump_prefetch(&mut self, _sender: &ComponentSender<Self>) {",
        );
        assert!(
            pump.contains("body_is_loading(&self.body_state)"),
            "the reason the restart is needed at all -- if this guard goes, \
             this whole test is about nothing"
        );
        let select = extract_brace_body(src, "Msg::SelectFolder(id) if inbox => {");
        assert!(
            select.contains("self.prefetch_inflight.clear();"),
            "fetches that never answer must not hold in-flight slots for \
             the rest of the session"
        );
    }

    /// T-099: the loading state a row is bound with has to come from the
    /// warm-up's own state. Anything else -- a constant, or "the preview is
    /// empty" -- is a skeleton that outlives the fetch it stands for.
    #[test]
    fn rows_take_their_loading_state_from_the_warm_up() {
        let src = include_str!("shell.rs");
        let active = extract_brace_body(src, "fn prefetch_active(&self) -> bool {");
        assert!(
            active.contains("!self.prefetch_inflight.is_empty()")
                && active.contains("!self.prefetch_queue.is_empty()"),
            "both halves of \"still fetching\" count: the chunk out with the \
             worker and the ones still queued"
        );
        let ready = extract_brace_body(
            src,
            concat!(
                "fn on_body_ready(&mut self, message_id: MessageId, ok: bool, ",
                "sender: &ComponentSender<Self>) {"
            ),
        );
        assert!(
            ready.contains("if !self.prefetch_active() {")
                && ready.contains("self.drop_finished_skeletons(sender);"),
            "the end of the warm-up must take the skeletons off the rows it \
             never reached, or a failed last fetch leaves them animating"
        );
        assert_eq!(
            ready
                .matches("self.repaint_row_for_body(&message_id, sender);")
                .count(),
            2,
            "both bodies repaint their own card: the warmed-up one and the \
             one the reader opened, whose row was bound before the snippet \
             existed"
        );
        assert!(
            !ready.contains("sync_refresh_reload_list"),
            "a body landing must never reload the page: that empties the \
             reader and scrolls the list back to the top"
        );
    }

    /// T-099: opening a message must not move the list/reader divider.
    ///
    /// The pane was a plain box in a horizontal box, so its width was its
    /// natural width -- and selecting a card changes what the card contains
    /// (the hover strip, the unread dot, a snippet arriving). The column
    /// moved under the reader for no reason the reader could see, the same
    /// defect T-097(6) fixed for the sidebar. A paned position is a number.
    #[test]
    fn the_list_and_the_reader_are_split_by_a_draggable_divider() {
        let src = include_str!("shell.rs");
        let view = extract_brace_body(src, "view! {");
        let split = view
            .split_once("add_css_class: \"list-pane\"")
            .expect("the list pane is in the view")
            .0;
        let split = &split[split
            .rfind("gtk::Paned {")
            .expect("the list pane sits in a paned")..];
        assert!(
            split.contains("set_position: model.list_width,"),
            "the divider is a stored number, not whatever the pane's contents \
             happen to measure this frame"
        );
        assert!(
            split.contains("sender.input(Msg::ListWidth(paned.position()));"),
            "a drag has to reach the model, or the width is lost on restart"
        );
        assert!(
            split.contains("set_resize_start_child: false,")
                && split.contains("set_shrink_start_child: false,"),
            "growing the window widens the mail, not the list, and a drag \
             cannot collapse the list past what its own rows need"
        );
        assert!(
            !include_str!("style.css").contains("min-width: 440px"),
            "a CSS floor on a paned child floors the divider too: it could be \
             dragged out and never back"
        );
    }

    /// T-101: a search hit shows words, not `=?UTF-8?B?...?=`.
    ///
    /// `messages.subject` and `sender_name` are supposed to hold display text,
    /// but on the owner's real mailbox 2527 of 2548 rows still hold the raw
    /// encoded word -- the list and the reading pane look right only because
    /// they decode at paint time. This popover built its labels straight from
    /// the row. Mutation: drop either call -> a Cyrillic hit is base64 again.
    #[test]
    fn a_search_hit_is_decoded_before_it_is_painted() {
        let src = include_str!("shell.rs");
        let fill = extract_brace_body(
            src,
            "fn fill_search_hits(&self, sender: &ComponentSender<Self>) {",
        );
        assert!(
            fill.contains("decode_encoded_words(&t.from.name)")
                && fill.contains("display_subject(&t.subject)"),
            "a search suggestion paints the row's stored header, so it has to \
             decode it the same way every other visible surface does"
        );
    }

    /// T-101: the search suggestions may not grow past the window.
    ///
    /// The owner typed into search on a mailbox whose messages carry long
    /// subjects and the popover "becomes enormous and can go outside the
    /// client window". Two separate ceilings are missing when it does: an
    /// ellipsizing label still *asks* for its whole text, and twenty hits
    /// (plus every `Load more` page after them) are taller than the desk.
    /// Mutation: drop either cap -> this fails.
    #[test]
    fn the_search_suggestions_cannot_outgrow_the_window() {
        let src = include_str!("shell.rs");
        let fill = extract_brace_body(
            src,
            "fn fill_search_hits(&self, sender: &ComponentSender<Self>) {",
        );
        assert!(
            fill.contains("from.set_max_width_chars(SEARCH_HIT_FROM_CHARS);")
                && fill.contains("sub.set_max_width_chars(SEARCH_HIT_SUBJECT_CHARS);"),
            "an ellipsized label asks for its whole text as its natural width,              so one long subject widens the popover past the window"
        );
        assert!(
            src.contains("search_scroller.set_max_content_height(MAX_SUGGESTION_HEIGHT);")
                && src.contains("search_scroller.set_propagate_natural_height(true);")
                && src.contains("search_popover.set_child(Some(&search_scroller));"),
            "the hit list scrolls past a screenful instead of running off the              bottom of the window, and a two-hit answer stays two hits tall"
        );
        let refill = extract_brace_body(
            src,
            "fn refill_search(&self, sender: &ComponentSender<Self>) {",
        );
        assert!(
            refill.contains("self.search_popover.set_size_request(width, -1);"),
            "a popover is centred on what it points at: without the field's              own width it opens halfway along the search box"
        );
        let laid_out = extract_brace_body(
            src,
            "fn popover_content_is_laid_out(popover: &gtk::Popover) -> bool {",
        );
        assert!(
            laid_out.contains("gtk::ScrolledWindow")
                && laid_out.contains("gtk::Viewport"),
            "the rows moved one level down into the scroller; a check that              stops at the scroller answers for the wrong widget"
        );
    }

    /// T-101: the reading pane must not set the window's minimum width.
    ///
    /// The owner, in Spam: "правая часть программы не адаптивная, текст
    /// сообщения и кнопки управления уходят за границу". A label that
    /// neither wraps nor ellipsizes asks for its whole text as a *minimum*,
    /// and a wrapping label's minimum is its longest unbreakable word -- and
    /// spam is where both live (a sentence for a display name, a URL for a
    /// subject). Every such minimum is the pane's, and the pane's is the
    /// shell's. Mutation: drop any one of these -> the toolbar leaves the
    /// window again on the first junk message.
    #[test]
    fn nothing_in_the_reading_pane_can_floor_the_window_width() {
        let src = include_str!("shell.rs");
        let view = extract_brace_body(src, "view! {");
        let pane = view
            .split_once("add_css_class: \"preview-pane\"")
            .expect("the reading pane is in the view")
            .1;
        for (css_class, guard) in [
            (
                "preview-subject",
                "set_wrap_mode: gtk::pango::WrapMode::WordChar,",
            ),
            (
                "meta-name",
                "set_ellipsize: gtk::pango::EllipsizeMode::End,",
            ),
            (
                "meta-email",
                "set_ellipsize: gtk::pango::EllipsizeMode::End,",
            ),
            ("letter", "set_wrap_mode: gtk::pango::WrapMode::WordChar,"),
            (
                "html-footer",
                "set_wrap_mode: gtk::pango::WrapMode::WordChar,",
            ),
        ] {
            let after = pane
                .split_once(&format!("add_css_class: \"{css_class}\""))
                .unwrap_or_else(|| panic!("`{css_class}` is in the reading pane"))
                .1;
            let label = &after[..after.find("},").unwrap_or(after.len())];
            assert!(
                label.contains(guard),
                "`{css_class}` needs `{guard}` or its text is the pane's floor"
            );
        }
        let attachments = extract_brace_body(src, "for attachment in &self.incoming_attachments {");
        assert!(
            attachments.contains("filename.set_max_width_chars("),
            "a 90-character filename opens the window wider than the desk"
        );
    }

    /// T-099: refreshing one row must not go through the model.
    ///
    /// `remove` + `insert` at a position is an `items-changed`, and GTK
    /// answers it by disposing the row widget; the list loses the widget
    /// holding its focus, falls back to the first item and scrolls there.
    /// Measured on the nested stand before the fix: one painted frame at
    /// offset 0 between two at 972 -- the flash of the top of the folder the
    /// owner reported -- and the list left at the top afterwards. Restoring
    /// the offset after the fact only adds a second wrong frame, so the pin
    /// here is on the splice itself, not on the scroll.
    #[test]
    fn refreshing_a_row_never_splices_the_model() {
        let src = include_str!("shell.rs");
        let body = extract_brace_body(
            src,
            "fn rebind_thread(&mut self, id: &str, sender: &ComponentSender<Self>) {",
        );
        assert!(
            body.contains("rows::repaint_live_row(&t, chip.as_deref(), pending, now);"),
            "the card on screen is written through in place"
        );
        assert!(
            !body.contains(&joined(&["self.list.", "remove(i)"]))
                && !body.contains(&joined(&["self.list.", "insert("])),
            "a snippet, a star or an unread dot is not worth rebuilding the \
             row widget for -- that is what scrolled the list to the top"
        );
        assert!(
            !body.contains("list_vadj"),
            "nothing scrolls anymore, so there is no offset to save and put \
             back; a saved offset would mean the splice is back"
        );
    }

    /// T-099: the thread list must not be in single-click-activate mode.
    /// GTK4 reads that flag as "this list behaves like a menu" and selects a
    /// row on pointer *enter*, so the selection followed the mouse across the
    /// list and left the reader showing a message no longer highlighted. The
    /// row is opened by the click gesture in `rows.rs`, on release, and
    /// nothing here listens for `activate` at all.
    #[test]
    fn the_thread_list_does_not_select_on_hover() {
        let src = include_str!("shell.rs");
        let init = extract_brace_body(
            src,
            concat!(
                "fn init(\n        _init: Self::Init,\n        root: Self::Root,\n",
                "        sender: ComponentSender<Self>,\n    ) -> ComponentParts<Self> {"
            ),
        );
        assert!(
            !init.contains(&joined(&["set_single_click", "_activate"])),
            "hover must not move the selection: the list is driven by clicks"
        );
    }

    /// T-098: the Welcome screen offers exactly one control, `Add account`,
    /// and no way out. Whatever routes there has to ask first whether a
    /// profile already exists -- otherwise a mailbox that is sitting on disk
    /// looks, from the only screen on show, like it was never configured.
    #[test]
    fn welcome_is_only_reachable_while_the_profile_is_empty() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::OpenWelcome => {");
        assert!(
            arm.contains("accounts_cache.is_empty()"),
            "OpenWelcome must check the profile before showing Welcome"
        );
        assert!(
            arm.contains("Screen::Inbox"),
            "an account holder asking for Welcome belongs on the Inbox"
        );
    }

    /// T-094: `AddMailbox` must hand the validated form to the
    /// provisioning thread -- never to `FakeMailStore`, and never to a
    /// shell-side `Core` call of its own (the probe belongs off the GTK
    /// thread, D11).
    #[test]
    fn add_mailbox_provisions_through_service_not_fake_store() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::AddMailbox => {");
        assert!(
            arm.contains("begin_provision"),
            "AddMailbox must go through begin_provision / spawn_provision"
        );
        assert!(
            arm.contains("ProvisionRequest::Password"),
            "AddMailbox must build ProvisionRequest::Password from the form"
        );
        assert!(
            arm.contains("accounts_cache") && arm.contains("AddAccountError::Duplicate"),
            "the duplicate check stays in the arm, against accounts_cache"
        );
        for forbidden in ["FakeMailStore", "add_account", "self.core"] {
            assert!(
                !arm.contains(forbidden),
                "AddMailbox must not contain {forbidden} -- provisioning is \
                 the service's door, on its own thread"
            );
        }
    }

    /// T-094: `Provisioned` is the wizard's only completion path. Failure
    /// must route through the wizard (never a toast), success must refill
    /// the sidebar from SQLite and wake the sync worker.
    #[test]
    fn provisioned_arm_routes_fail_to_wizard_and_success_to_sync() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::Provisioned { gen, result } => {");
        assert!(
            arm.contains("provisioned_effect(gen, self.wizard_gen, result)"),
            "the arm must decide through the pure provisioned_effect"
        );
        assert!(
            arm.contains("wizard.fail(message)"),
            "a manual provisioning failure returns to the IMAP form"
        );
        assert!(
            arm.contains("wizard.submit") && arm.contains("refill_accounts"),
            "success records the account id and refills the sidebar"
        );
        assert!(
            arm.contains("wake_sync"),
            "success must wake the sync worker so FolderSynced can finish the wizard"
        );
        assert!(
            !arm.contains("show_toast"),
            "a provisioning failure is wizard state, not a toast"
        );
    }

    /// T-165: the session-account button is the one wizard control that
    /// does provision straight away -- it has nothing to fill in, because
    /// the address and the token both come from the account manager. It
    /// must go through the system arm specifically: routing it through
    /// `ProvisionRequest::Oauth` would start a browser sign-in with a
    /// client ID this build does not have.
    #[test]
    fn the_system_account_button_provisions_through_the_system_arm() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::UseSystemAccount(handle) => {");
        assert!(arm.contains("ProvisionRequest::SystemAccount { handle }"));
        assert!(arm.contains("begin_provision"));
        assert!(
            !arm.contains("ProvisionRequest::Oauth") && !arm.contains("GoogleClientConfig"),
            "the session account must not start a browser sign-in"
        );
    }

    /// The probe answers on a thread, so a reply can land after the user
    /// has closed and reopened the wizard. Same guard as `Msg::Provisioned`.
    #[test]
    fn a_late_system_accounts_reply_is_dropped() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::SystemAccountsFound { gen, accounts } => {");
        assert!(
            arm.contains("if gen != self.system_accounts_gen"),
            "a reply for a closed wizard must be dropped, not applied"
        );
    }

    /// D11: the probe is a D-Bus round trip that GOA may turn into a
    /// network call, so it must never be made from the update arm itself.
    /// T-167 moved it from opening the wizard to entering the Linux level,
    /// which is the only screen that asks the question.
    #[test]
    fn the_system_accounts_probe_runs_off_the_gtk_thread() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::ChooseSystem => {");
        assert!(
            arm.contains("spawn_system_accounts"),
            "the wizard must ask the service to probe on its own thread"
        );
        assert!(
            !arm.contains("Goa::") && !arm.contains("mail_accounts()"),
            "the shell must not talk to the account manager directly (D9)"
        );
        let opening = extract_brace_body(src, "Msg::OpenAddAccount => {");
        assert!(
            !opening.contains("spawn_system_accounts"),
            "opening the wizard lands on level one, which does not need the answer"
        );
    }

    /// T-167: the three states of the Linux level are exclusive, and each
    /// one is wrong on the other two's screen. Showing the instructions
    /// while the probe is still out would claim there are no accounts
    /// before we know; showing them on the IMAP branch would explain
    /// Online Accounts to someone typing a server name.
    #[test]
    fn the_linux_level_shows_exactly_one_of_wait_list_or_instructions() {
        let mut wizard = Wizard::default();
        wizard.choose_system();

        assert!(show_system_probing(&wizard, true));
        assert!(!show_system_accounts(&wizard, true, true));
        assert!(!show_system_empty(&wizard, true, false));

        assert!(show_system_accounts(&wizard, false, true));
        assert!(!show_system_probing(&wizard, false));
        assert!(!show_system_empty(&wizard, false, true));

        assert!(show_system_empty(&wizard, false, false));
        assert!(!show_system_accounts(&wizard, false, false));
    }

    /// The screen must not argue with itself: the Linux lede claims the
    /// desktop is signed into accounts, which is exactly what the empty
    /// state denies.
    #[test]
    fn the_level_lede_gives_way_to_the_instructions_it_would_contradict() {
        let mut wizard = Wizard::default();
        wizard.choose_system();
        assert!(
            show_lede(&wizard, true, false),
            "the wait line keeps its lede"
        );
        assert!(show_lede(&wizard, false, true), "so does the list");
        assert!(
            !show_lede(&wizard, false, false),
            "the instructions are the explanation; the lede would deny them"
        );

        let mut imap = Wizard::default();
        assert!(
            show_lede(&imap, false, false),
            "level one always has its question"
        );
        imap.choose_imap();
        assert!(show_lede(&imap, false, false));
        imap.step = WizardStep::Connecting;
        assert!(
            !show_lede(&imap, false, false),
            "progress has a label of its own, not a lede"
        );
    }

    /// Every bundled icon a widget asks for by name must actually be in
    /// the compiled resource. A missing one is not a build error: GTK
    /// draws the broken-image glyph, and only a person looking at the
    /// screen would notice.
    #[test]
    fn every_icon_the_shell_names_is_in_the_bundle() {
        let src = include_str!("shell.rs");
        let manifest = include_str!("../assets/icons/fm-icons.gresource.xml");
        let mut checked = 0;
        for (index, _) in src.match_indices("set_icon_name: Some(\"fm-") {
            let rest = &src[index + "set_icon_name: Some(\"".len()..];
            let name = &rest[..rest.find('"').expect("icon name is quoted")];
            assert!(
                manifest.contains(&format!("<file>{name}.svg</file>")),
                "{name} is used by the shell but not compiled into fm-icons.gresource"
            );
            checked += 1;
        }
        assert!(
            checked >= 2,
            "the icon names must be found, not silently skipped"
        );
    }

    /// None of the three belongs to any other level.
    #[test]
    fn the_session_accounts_never_appear_outside_their_own_level() {
        let mut wizard = Wizard::default();
        assert!(
            !show_system_accounts(&wizard, false, true),
            "level one asks which branch, and answers nothing itself"
        );
        assert!(!show_system_empty(&wizard, false, false));
        assert!(show_source(&wizard));

        wizard.choose_imap();
        assert!(!show_system_accounts(&wizard, false, true));
        assert!(!show_system_empty(&wizard, false, false));
        assert!(!show_source(&wizard));

        wizard.step = WizardStep::OtherForm;
        assert!(!show_system_accounts(&wizard, false, true));

        wizard.choose_system();
        wizard.step = WizardStep::Connecting;
        assert!(!show_system_accounts(&wizard, false, true));
        assert!(!show_system_empty(&wizard, false, false));
        wizard.step = WizardStep::Ready;
        assert!(!show_system_accounts(&wizard, false, true));
    }

    /// Provider buttons are configuration presets only. They must keep the
    /// Add-account flow in the manual IMAP form and never invoke OAuth.
    #[test]
    fn provider_presets_fill_manual_form_not_oauth() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::UseMailboxPreset(preset) => {");
        assert!(arm.contains("apply_mailbox_preset(preset)"));
        assert!(arm.contains("WizardStep::OtherForm"));
        assert!(
            !arm.contains("ProvisionRequest::Oauth") && !arm.contains("begin_provision"),
            "a preset is a local form fill, never a browser provisioning flow"
        );
    }

    #[test]
    fn manual_provider_presets_have_the_documented_secure_servers() {
        let google = mailbox_preset_values(MailboxPreset::Google);
        assert_eq!(
            (
                google.imap_host,
                google.imap_port,
                google.smtp_host,
                google.smtp_port
            ),
            ("imap.gmail.com", "993", "smtp.gmail.com", "587")
        );
        assert_eq!(google.imap_security, MailSecurity::Ssl);
        // T-103: submission over STARTTLS/587, the port that is open where
        // 465 is not. Both are TLS -- this is not a downgrade.
        assert_eq!(google.smtp_security, MailSecurity::StartTls);

        let microsoft = mailbox_preset_values(MailboxPreset::Microsoft);
        assert_eq!(
            (
                microsoft.imap_host,
                microsoft.imap_port,
                microsoft.smtp_host,
                microsoft.smtp_port,
            ),
            (
                "outlook.office365.com",
                "993",
                "smtp-mail.outlook.com",
                "587",
            )
        );
        assert_eq!(microsoft.imap_security, MailSecurity::Ssl);
        assert_eq!(microsoft.smtp_security, MailSecurity::StartTls);

        let yandex = mailbox_preset_values(MailboxPreset::Yandex);
        assert_eq!(
            (
                yandex.imap_host,
                yandex.imap_port,
                yandex.smtp_host,
                yandex.smtp_port
            ),
            ("imap.yandex.com", "993", "smtp.yandex.com", "465")
        );
        assert_eq!(yandex.imap_security, MailSecurity::Ssl);
        assert_eq!(yandex.smtp_security, MailSecurity::Ssl);
    }

    /// T-094: the wizard leaves `Synchronizing` on the first FolderSynced
