    #[test]
    fn a_frame_log_is_written_only_where_a_harness_actually_asked() {
        assert_eq!(opt_in_path(FRAME_LOG_VAR, None), None);
        // An empty variable is a broken harness path, not the file `""`.
        assert_eq!(opt_in_path(FRAME_LOG_VAR, Some(OsStr::new(""))), None);
        assert_eq!(
            opt_in_path(FRAME_LOG_VAR, Some(OsStr::new("/tmp/frames.log"))),
            Some(PathBuf::from("/tmp/frames.log"))
        );
        // T-054: the pointer probe uses the same door, and must refuse an
        // empty path for the same reason -- a harness that built its path
        // wrongly should get nothing, not a file named `""`.
        assert_eq!(opt_in_path(POINTER_PROBE_VAR, Some(OsStr::new(""))), None);
        assert_eq!(
            opt_in_path(POINTER_PROBE_VAR, Some(OsStr::new("/tmp/pick.log"))),
            Some(PathBuf::from("/tmp/pick.log"))
        );
    }

    #[test]
    fn a_frame_line_carries_five_measured_fields_and_nothing_else() {
        let line = format_frame_line(41, 1_234_567, Duration::from_micros(2_500), 16_666, 4_820.5);
        assert_eq!(line, "41 1234567 2500 16666 4820.5\n");
        // Sub-microsecond paints must still produce a parsable integer, and
        // an unknown refresh interval stays the explicit `0` the harness
        // knows how to treat as "GDK did not say".
        let fast = format_frame_line(0, 0, Duration::from_nanos(900), 0, 0.0);
        assert_eq!(fast, "0 0 0 0 0.0\n");
        for line in [line, fast] {
            let fields: Vec<&str> = line.trim_end().split(' ').collect();
            assert_eq!(fields.len(), 5);
            assert!(fields[..4].iter().all(|field| field.parse::<i64>().is_ok()));
            assert!(fields[4].parse::<f64>().is_ok());
        }
    }

    #[test]
    fn a_probe_line_carries_geometry_and_never_a_word_of_content() {
        let line = format_probe_line(
            688.0,
            520.4,
            "GtkButton",
            &["text-button".to_string(), "btn-primary".to_string()],
            Some((632.0, 528.0, 176.0, 48.0)),
        );
        assert_eq!(
            line,
            "688 520 GtkButton text-button,btn-primary 632 528 176 48\n"
        );
        // A pick can land on a widget with no style class at all, and it can
        // find nothing: both must stay parsable, and "nothing there" must not
        // read as "there, at 0,0".
        let empty = format_probe_line(0.0, 0.0, "-", &[], None);
        assert_eq!(empty, "0 0 - - - - - -\n");
        for line in [line, empty] {
            assert_eq!(line.trim_end().split(' ').count(), 8);
        }
    }

    /// T-054: the probe exists to aim a pointer, and a row under that pointer
    /// carries a sender and a subject. Reading any of the properties below
    /// would put message content in a file on disk (D14) -- and the only
    /// reason the harness can be given this file at all is that it cannot.
    #[test]
    fn the_pointer_probe_reads_geometry_only_never_widget_text() {
        let src = include_str!("shell.rs");
        let body = extract_brace_body(
            src,
            "fn attach_pointer_probe(\n    native: &gtk::Widget,\n    window: &gtk::Window,\n    sink: &Rc<RefCell<std::fs::File>>,\n) {",
        );
        for forbidden in [
            ".label()",
            ".text()",
            ".tooltip_text()",
            ".accessible_role()",
            ".title()",
            "buffer()",
        ] {
            assert!(
                !body.contains(forbidden),
                "attach_pointer_probe must not read {forbidden}: the probe file \
                 is written while a mailbox is on screen, and widget text there \
                 is message content"
            );
        }
        // The pick itself is the point: a probe that stopped calling it would
        // still write plausible lines, and every one of them would describe
        // the window instead of the widget a click will actually reach.
        assert!(
            body.contains("pick("),
            "the probe must report GtkWidget::pick"
        );
    }

    /// T-054: compose is a separate toplevel. A probe that only watched the
    /// shell window would leave the click-through suite blind exactly where a
    /// modal surface can swallow the pointer, which is the failure it exists
    /// to catch -- so the probe has to follow every window this process shows,
    /// and it has to refuse to report the same motion twice.
    #[test]
    fn the_pointer_probe_follows_every_window_the_process_opens() {
        let src = include_str!("shell.rs");
        let install = extract_brace_body(
            src,
            "fn install_pointer_probe(window: &gtk::ApplicationWindow, path: PathBuf) {",
        );
        assert!(
            install.contains("attach_pointer_probe_to_natives(&sink)")
                && install.contains("timeout_add_local(POINTER_PROBE_SWEEP"),
            "the probe must keep finding surfaces the shell opens later, or \
             compose and every popover stay unclickable"
        );
        let sweep = extract_brace_body(
            src,
            "fn attach_pointer_probe_to_natives(sink: &Rc<RefCell<std::fs::File>>) {",
        );
        assert!(
            sweep.contains("gtk::Window::list_toplevels()"),
            "compose exists from startup, so waiting for a new toplevel would \
             never find it -- every toplevel on screen has to be swept"
        );
        let below = extract_brace_body(
            src,
            "fn attach_pointer_probe_below(\n    widget: gtk::Widget,\n    window: &gtk::Window,\n    sink: &Rc<RefCell<std::fs::File>>,\n) {",
        );
        assert!(
            below.contains("widget.is::<gtk::Native>()"),
            "a popover is a surface of its own: only a GtkNative gets its own \
             motion, so the walk has to probe each of them"
        );
        let attach = extract_brace_body(
            src,
            "fn attach_pointer_probe(\n    native: &gtk::Widget,\n    window: &gtk::Window,\n    sink: &Rc<RefCell<std::fs::File>>,\n) {",
        );
        assert!(
            attach.contains("has_pointer_probe(native)"),
            "attaching twice would write every motion twice, and the harness \
             reads the last line as the answer for the point it just moved to"
        );
        assert!(
            attach.contains("compute_point(&reference")
                && attach.contains("compute_bounds(&reference)"),
            "a popover has coordinates no window manager can name, so every \
             pick must be reported in the toplevel's own space"
        );
        let guard = extract_brace_body(src, "fn has_pointer_probe(widget: &gtk::Widget) -> bool {");
        assert!(
            guard.contains("observe_controllers()") && guard.contains("POINTER_PROBE_CONTROLLER"),
            "the duplicate guard must ask GTK what is already installed"
        );
    }

    #[test]
    fn the_frame_log_records_where_the_list_was_scrolled_to() {
        // Without the offset a benchmark cannot tell a fast scroll from a
        // list that never moved: both paint cheap frames.
        let still = format_frame_line(7, 100, Duration::from_micros(1_000), 16_666, 0.0);
        let moved = format_frame_line(8, 200, Duration::from_micros(1_000), 16_666, 1_920.0);
        assert_ne!(
            still.rsplit(' ').next().unwrap(),
            moved.rsplit(' ').next().unwrap()
        );
    }

    /// T-054: an `add_overlay` child is drawn on top of the whole screen,
    /// and GTK hit testing does not skip an empty expanding box -- so a
    /// wrapper that is always visible picks every pointer event under it
    /// and drops it, while keyboard focus (which never hit-tests) keeps
    /// working. That is how the shell shipped with a completely dead mouse
    /// and a green keyboard E2E, and it is what T-054's pointer run was
    /// really failing on. Every overlay child must therefore either watch
    /// its own visibility or opt out of hit testing; the inner widget's
    /// `set_visible` does not count, because an invisible child does not
    /// make its visible parent untargetable.
    ///
    /// Mutation: drop the `#[watch] set_visible` from the settings overlay
    /// wrapper -> this test is red.
    #[test]
    fn every_overlay_child_watches_its_visibility_or_cannot_be_targeted() {
        let src = include_str!("shell.rs");
        // Built by concatenation: a literal needle would match this test's
        // own source and the guard could never be red (same reason as the
        // whole-file guards in rows.rs).
        let marker = ["add_overlay = &gtk::", "Box {"].concat();
        let marker = marker.as_str();
        let mut offset = 0;
        let mut checked = 0;
        while let Some(at) = src[offset..].find(marker) {
            let start = offset + at + marker.len();
            let mut depth = 1i32;
            let mut end = start;
            for (index, ch) in src[start..].char_indices() {
                match ch {
                    '{' => depth += 1,
                    '}' => {
                        depth -= 1;
                        if depth == 0 {
                            end = start + index;
                            break;
                        }
                    }
                    _ => {}
                }
            }
            // Only the box's own properties count: they are written before
            // its first child block, and a nested widget's `set_visible` is
            // exactly the false reassurance this test exists to reject.
            let body = &src[start..end];
            // Comments are dropped first: a `//` line that merely *mentions*
            // `set_visible` (this fix's own explanation does) would otherwise
            // satisfy the guard while the property is gone.
            let own: String = body
                .split('{')
                .next()
                .unwrap_or("")
                .lines()
                .filter(|line| !line.trim_start().starts_with("//"))
                .collect::<Vec<_>>()
                .join("\n");
            assert!(
                own.contains("set_visible") || own.contains("set_can_target: false"),
                "an overlay child that is always visible swallows pointer \
                 input for the whole window; give it a visibility watch or \
                 set_can_target: false:\n{own}"
            );
            checked += 1;
            offset = end;
        }
        assert!(
            checked >= 2,
            "the overlay children moved; this guard found only {checked}"
        );
    }

    #[test]
    fn the_frame_tap_observes_frames_instead_of_requesting_them() {
        // A tick callback keeps asking GDK for the next frame, so a scroll
        // benchmark built on one measures the instrument as much as the app
        // (and pays idle wake-ups in every session that forgets to unset the
        // variable). Pin the observing signals, and pin the absence of the
        // requesting API in the tap.
        let src = include_str!("shell.rs");
        let tap = src
            .split_once("fn install_frame_log(")
            .expect("the frame tap is installed by install_frame_log")
            .1;
        let tap = tap.split_once("\n}\n").expect("install_frame_log ends").0;
        assert!(tap.contains("connect_before_paint"));
        assert!(tap.contains("connect_after_paint"));
        assert!(!tap.contains("add_tick_callback"));
    }

    /// rustfmt breaks the `DraftSaved` arm's pattern over five lines, and
    /// the `tx.emit` in `save_current_draft` opens with exactly the same
    /// two -- so a contract about the arm anchors on the whole pattern, up
    /// to the `=>` only the arm has.
    const DRAFT_SAVED_ARM: &str = concat!(
        "Msg::DraftSaved {\n                session,\n                gen,\n",
        "                result,\n            } => {"
    );

    /// Closing compose is the one point where an unsaved draft must reach
    /// disk. `Msg::CloseCompose` calls `save_current_draft`, which returns
    /// early while a previous autosave is still in flight, and the only
    /// retry (`Msg::DraftSaved`) used to be gated on the window still being
    /// visible -- which `CloseCompose` has just turned off.
    #[test]
    fn closing_compose_saves_even_while_an_autosave_is_in_flight() {
        let src = include_str!("shell.rs");
        let saved = source_block(src, DRAFT_SAVED_ARM);
        assert!(
            !saved.contains("self.compose_dirty && self.compose.is_visible()"),
            "the retry after an in-flight save must not depend on the compose \
             window still being open -- CloseCompose hides it first"
        );
        let close = extract_brace_body(src, "Msg::CloseCompose => {");
        assert!(
            close.contains("compose_save_inflight") || close.contains("compose_close_pending"),
            "CloseCompose must record that a close is waiting on the in-flight \
             save instead of calling a door that silently returns"
        );
    }

    /// A response draft is created under the account the letter lives in
    /// (`begin_response_draft` -> `account_for_thread`), so every compose
    /// door has to act on that account. Reading `current_account` instead
    /// makes Core's owner check (`save_draft` -> PermissionDenied) reject
    /// both autosave and Send whenever the merged view is open.
    #[test]
    fn compose_doors_act_on_the_drafts_account_not_the_menus() {
        let src = include_str!("shell.rs");
        let save = extract_brace_body(
            src,
            "fn save_current_draft(&mut self, gen: u64, sender: &ComponentSender<Self>) {",
        );
        assert!(
            !save.contains("self.current_account"),
            "saving a draft must use the account that owns the draft"
        );
        let send = extract_brace_body(src, "Msg::Send => {");
        assert!(
            !send.contains("self.current_account"),
            "sending must use the account that owns the draft"
        );
        let discard = extract_brace_body(src, "Msg::DiscardDraft => {");
        assert!(
            !discard.contains("self.current_account"),
            "discarding must use the account that owns the draft"
        );
    }

    /// A hit opened from the merged view carries its own mailbox. Moving
    /// only `self.folder` leaves `current_account` on the previous mailbox,
    /// and `fetch_page` then asks Core for "account A, folder of account B".
    #[test]
    fn open_search_hit_moves_to_the_hits_account() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::OpenSearchHit(id) => {");
        assert!(
            arm.contains("account_id"),
            "opening a hit must move the shell to the mailbox the hit is in, \
             not only to its folder id"
        );
    }

    /// Every timestamp the shell paints has to be measured against the
    /// same clock the group headers are stamped with. Against the fixture
    /// clock anything newer than 2024-05-20 falls into `format_clock`'s
    /// "Today" branch and prints a time of day, so a letter under an
    /// "Older" header showed "3:42 PM".
    #[test]
    fn painted_timestamps_use_the_wall_clock() {
        let src = include_str!("shell.rs");
        let live = src.split("mod tests").next().unwrap();
        assert!(
            !live.contains("format_clock(t.date, FIXTURE_NOW)")
                && !live.contains("format_clock(msg.date, FIXTURE_NOW)"),
            "a painted timestamp must be measured against the wall clock, \
             the same clock `stamp_headers` uses"
        );
        // And what the two clocks do to one real letter: 200 days back is
        // a date against the wall clock, and a clock time against the
        // fixture constant -- which is the whole defect, in one line.
        let now = wall_clock_now();
        let old = now - 200 * 86_400;
        assert!(
            !format_clock(old, now).contains(':'),
            "a letter 200 days old must not be painted as a time of day, got {:?}",
            format_clock(old, now)
        );
        assert!(
            format_clock(old, FIXTURE_NOW).contains(':'),
            "the fixture constant is in the past, so every real letter looks \
             like it arrived today -- that is why it may not reach a label"
        );
    }

    /// T-046: "GTK adds a plaintext quote". An HTML letter -- the default
    /// rendering for `multipart/alternative`, since `prefer_plain` is off
    /// by default -- produces no quote at all.
    #[test]
    fn replying_to_an_html_letter_quotes_it() {
        let state = BodyState::Ready(PreparedBody::Html {
            sanitized: "<p>hello</p><p>world</p>".to_string(),
            report: feathermail_html::SanitizeReport::default(),
            attachments: 0,
            allow_remote_images: false,
        });
        let quote = compose_quote(&state);
        assert!(
            quote.contains("> hello"),
            "a reply to an HTML letter must carry the quoted text, got {quote:?}"
        );
    }

    /// T-121 made `refill_nav` asynchronous: `folders_cache` is refreshed
    /// only when `Msg::NavLoaded` lands. Both recovery branches still ask
    /// the cache on the spot, so they read the folder set that the just
    /// deleted account/folder is still in and never fire.
    #[test]
    fn folder_fallback_does_not_read_the_stale_nav_cache() {
        let src = include_str!("shell.rs");
        for marker in [
            "Msg::RemoveAccountConfirm(id) => {",
            "Msg::DeleteFolderConfirmed(folder_id) => {",
        ] {
            let arm = extract_brace_body(src, marker);
            assert!(
                !arm.contains(".folders_cache"),
                "{marker} decides on a folder set that `refill_nav` has not \
                 fetched yet -- the fallback must live where NavLoaded lands"
            );
        }
    }

    /// Every other compose door refuses to act while a save is in flight
    /// (`Msg::Send`, `Msg::PickAttachment`). Discard deletes the row
    /// straight away, so a save thread that has not taken the `core` lock
    /// yet re-inserts the draft it was told to throw away.
    #[test]
    fn discard_waits_for_the_in_flight_save() {
        let src = include_str!("shell.rs");
        let arm = extract_brace_body(src, "Msg::DiscardDraft => {");
        assert!(
            arm.contains("compose_save_inflight"),
            "Discard must not race the background save that is about to \
             write the same draft id back"
        );
        assert!(
            arm.contains("PendingDiscard {"),
            "the parked delete has to carry its own mailbox and row: by the \
             time the save answers, the reader may be writing the next letter"
        );
    }

    /// The subtle half of that fix: the reader can discard a draft and open
    /// the next letter before the save answers. The session guard would
    /// then drop the answer -- and with it the delete -- leaving the
    /// thrown-away draft in Drafts, so the parked discard is settled first.
    #[test]
    fn a_parked_discard_outlives_the_window_that_asked_for_it() {
        let src = include_str!("shell.rs");
        let arm = source_block(src, DRAFT_SAVED_ARM);
        let discard = arm
            .find("compose_discard_pending")
            .expect("DraftSaved settles a parked discard");
        let guard = arm
            .find("if !compose_reply_is_current")
            .expect("DraftSaved drops a previous session's answer");
        assert!(
            discard < guard,
            "a discard parked by a window that is already gone must be \
             settled before the session guard returns"
        );
    }

    /// The pure half of the close/save race. Closing hides the window
    /// first, so a retry that asks whether the window is visible drops
    /// exactly the edits the close was meant to write.
    #[test]
    fn a_closing_compose_window_still_earns_its_save() {
        assert!(!draft_save_retry(false, true, false), "nothing to write");
        assert!(!draft_save_retry(false, false, true), "nothing to write");
        assert!(draft_save_retry(true, true, false), "the ordinary autosave");
        assert!(
            draft_save_retry(true, false, true),
            "the window is hidden because it is closing -- that is the one \
             moment an unsaved draft has to reach disk"
        );
        assert!(
            !draft_save_retry(true, false, false),
            "a hidden window nobody is closing has nothing to say"
        );
    }

    /// Same guard as `body_reply_is_current`, stated where it is decided.
    #[test]
    fn a_previous_compose_sessions_answer_is_not_current() {
        assert!(compose_reply_is_current(7, 7));
        assert!(!compose_reply_is_current(8, 7), "the window was replaced");
    }

    /// The three doors that would otherwise have carried a stale account:
